def pairrule(inp, out):
    Hh,Ww=len(inp),len(inp[0]); mis=[]
    def clear_line(r,c,dr,dc):
        # walk both directions collecting 7 positions with only bg between
        left=None; rr,cc=r+dr,c+dc
        while 0<=rr<Hh and 0<=cc<Ww:
            if inp[rr][cc]==7: left=(rr,cc); break
            if inp[rr][cc]!=4: break
            rr+=dr; cc+=dc
        right=None; rr,cc=r-dr,c-dc
        while 0<=rr<Hh and 0<=cc<Ww:
            if inp[rr][cc]==7: right=(rr,cc); break
            if inp[rr][cc]!=4: break
            rr-=dr; cc-=dc
        return left is not None and right is not None
    for r in range(Hh):
        for c in range(Ww):
            if inp[r][c]==4:
                pred = clear_line(r,c,0,1) or clear_line(r,c,1,0)
                act = out[r][c]==3
                if pred!=act: mis.append((r,c,pred,act))
    return mis
